ALTER TABLE public.zalo_oa_config ADD COLUMN IF NOT EXISTS token_version bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS refresh_lease uuid, ADD COLUMN IF NOT EXISTS refresh_started_at timestamptz, ADD COLUMN IF NOT EXISTS refresh_last_success_at timestamptz, ADD COLUMN IF NOT EXISTS refresh_next_at timestamptz, ADD COLUMN IF NOT EXISTS refresh_failures integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS refresh_error text, ADD COLUMN IF NOT EXISTS refresh_blocked boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS scheduler_last_at timestamptz, ADD COLUMN IF NOT EXISTS queue_last_at timestamptz;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS zalo_next_attempt_at timestamptz;
CREATE OR REPLACE FUNCTION public.zalo_refresh_claim(p_version bigint,p_lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN UPDATE public.zalo_oa_config SET refresh_lease=p_lease,refresh_started_at=clock_timestamp() WHERE id=1 AND token_version=p_version AND refresh_lease IS NULL AND NOT refresh_blocked AND status='connected' AND (refresh_next_at IS NULL OR refresh_next_at<=clock_timestamp()); RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.zalo_refresh_finish(p_version bigint,p_lease uuid,p_access text,p_refresh text,p_expires timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF length(p_access)<10 OR length(p_refresh)<10 OR p_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Invalid token response'; END IF; UPDATE public.zalo_oa_config SET access_token=p_access,refresh_token=p_refresh,token_expires_at=p_expires,token_version=token_version+1,refresh_lease=NULL,refresh_started_at=NULL,refresh_last_success_at=clock_timestamp(),refresh_next_at=p_expires-interval '2 hours',refresh_failures=0,refresh_error=NULL,refresh_blocked=false,last_error=NULL,status='connected',updated_at=clock_timestamp() WHERE id=1 AND token_version=p_version AND refresh_lease=p_lease; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.zalo_token_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN IF NEW.access_token IS DISTINCT FROM OLD.access_token AND NEW.token_version=OLD.token_version THEN NEW.token_version=OLD.token_version+1; NEW.refresh_lease=NULL; NEW.refresh_started_at=NULL; NEW.refresh_blocked=false; NEW.refresh_failures=0; NEW.refresh_error=NULL; NEW.refresh_next_at=NEW.token_expires_at-interval '2 hours'; END IF; RETURN NEW; END $$;
CREATE TRIGGER zalo_token_revision BEFORE UPDATE ON public.zalo_oa_config FOR EACH ROW EXECUTE FUNCTION public.zalo_token_revision();
REVOKE ALL ON FUNCTION public.zalo_refresh_claim(bigint,uuid), public.zalo_refresh_finish(bigint,uuid,text,text,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.zalo_refresh_claim(bigint,uuid), public.zalo_refresh_finish(bigint,uuid,text,text,timestamptz) TO service_role;
REVOKE ALL ON FUNCTION public.zalo_token_revision() FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS notifications_zalo_retry ON public.notifications(zalo_next_attempt_at) WHERE zalo_status IN ('pending','failed');